export type EffectiveAudioMode = 'spoken_presenter' | 'off_camera_voiceover' | 'ambient' | 'asmr' | 'no_speech';

export interface StyleDirectorSpec {
  id: string;
  concept: string;
  audienceExperience: string;
  openingVisual: string;
  shotComposition: string;
  sceneSelection: string;
  productInteraction: string;
  presenterVisibility: string;
  humanPerformance: string;
  defaultAudioMode: Extract<EffectiveAudioMode, 'spoken_presenter' | 'off_camera_voiceover'>;
  allowSoundOnly: boolean;
  voiceOrAudio: string;
  storytellingObjective: string;
  relevantProductInformation: string;
  naturalEnding: string;
  hardFailures: string[];
}

function define(spec: StyleDirectorSpec): StyleDirectorSpec { return spec; }

